const allItems = $input.all();
const personName = $('Config').first().json.Person1Name;

let person = null;

if (allItems.length > 1) {
  const match = allItems.find(item => item.json.name?.toLowerCase() === personName.toLowerCase());
  if (match) person = match.json;
}
if (!person) {
  const first = $input.first().json;
  const arr = Array.isArray(first) ? first : (first?.people ?? []);
  const match = arr.find(p => p.name?.toLowerCase() === personName.toLowerCase());
  if (match) person = match;
}
if (!person) {
  const first = $input.first().json;
  if (first?.name?.toLowerCase() === personName.toLowerCase()) person = first;
}
if (!person) throw new Error(`"${personName}" not found in Immich.`);

return [{ json: { id: person.id, name: person.name } }];

const person1Id = $input.first().json.id;
const person1Name = $input.first().json.name;

const config = $('Config').first().json;
const baseUrl = config.ImmichBaseURL;
const apiKey = config.APIKey;

const searchResult = await helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/search/person`,
  headers: { 'x-api-key': apiKey },
  qs: { name: config.Person2Name },
  json: true
});

const arr = Array.isArray(searchResult) ? searchResult : (searchResult?.people ?? []);
const person2Name = config.Person2Name;
const person2 = arr.find(p => p.name?.toLowerCase() === person2Name.toLowerCase());

if (!person2) {
  throw new Error(`"${person2Name}" not found in Immich. Available: ${arr.map(p => p.name).join(', ')}`);
}

console.log(`Person 1: ${person1Name} (${person1Id})`);
console.log(`Person 2: ${person2.name} (${person2.id})`);

return [{
  json: {
    person1Id,
    person2Id: person2.id,
    person1Name,
    person2Name: person2.name,
    AlbumID: config.AlbumID,
    ImmichBaseURL: baseUrl,
    APIKey: apiKey,
    DaysBack: config.DaysBack ?? 2,
    TelegramBotToken: config.TelegramBotToken,
    TelegramChatID: config.TelegramChatID
  }
}];

const ctx = $input.first().json;
const person1Id = ctx.person1Id;
const person2Id = ctx.person2Id;
const baseUrl = ctx.ImmichBaseURL;
const apiKey = ctx.APIKey;
const daysBack = ctx.DaysBack ?? 2;

const sinceDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000).toISOString();
console.log(`Fetching photos since: ${sinceDate} (last ${daysBack} days)`);

let allItems = [];
let page = 1;
const size = 1000;

while (true) {
  const data = await helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}/api/search/metadata`,
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': apiKey
    },
    body: {
      personIds: [person1Id],
      page,
      size,
      withPeople: true,
      takenAfter: sinceDate
    },
    json: true
  });

  const items = data?.assets?.items ?? [];
  allItems = allItems.concat(items);
  console.log(`Page ${page}: ${items.length} items, total so far: ${allItems.length}`);

  if (!data?.assets?.nextPage) break;
  page++;
}

console.log(`Total assets in last ${daysBack} days: ${allItems.length}`);

const coupleItems = allItems.filter(photo => {
  const people = photo.people ?? [];
  if (people.length !== 2) return false;
  const ids = people.map(p => p.id);
  return ids.includes(person1Id) && ids.includes(person2Id);
});

console.log(`Couple-only photos (last ${daysBack} days): ${coupleItems.length}`);

const ids = coupleItems.map(p => p.id);

return [{
  json: {
    ids,
    count: ids.length,
    totalFetched: allItems.length,
    person1Name: ctx.person1Name,
    person2Name: ctx.person2Name,
    AlbumID: ctx.AlbumID,
    ImmichBaseURL: baseUrl,
    TelegramBotToken: ctx.TelegramBotToken,
    TelegramChatID: ctx.TelegramChatID,
    sinceDate
  }
}];

const result = $input.first().json;
const added = result?.successfullyAdded ?? [];
const existing = result?.alreadyInAlbum ?? [];
const p1 = $('Fetch & Filter Couple Photos').first().json.person1Name;
const p2 = $('Fetch & Filter Couple Photos').first().json.person2Name;
const count = $('Fetch & Filter Couple Photos').first().json.count;
const total = $('Fetch & Filter Couple Photos').first().json.totalFetched;
const since = $('Fetch & Filter Couple Photos').first().json.sinceDate;
const botToken = $('Fetch & Filter Couple Photos').first().json.TelegramBotToken;
const chatId = $('Fetch & Filter Couple Photos').first().json.TelegramChatID;

const message = `📸 *Immich Couple Album Update*

✅ ${added.length} new photo(s) added
👫 ${p1} & ${p2}
🔁 ${existing.length} already in album
🔍 ${count} couple photos found / ${total} scanned
📅 Since: ${new Date(since).toLocaleDateString('en-CA')}`;

await helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${botToken}/sendMessage`,
  headers: { 'Content-Type': 'application/json' },
  body: {
    chat_id: chatId,
    text: message,
    parse_mode: 'Markdown'
  },
  json: true
});

console.log(`Telegram notified: ${added.length} added, ${existing.length} existing.`);

return [{
  json: {
    status: 'success',
    couple: `${p1} & ${p2}`,
    newlyAdded: added.length,
    alreadyInAlbum: existing.length,
    couplePhotos: count,
    totalFetched: total,
    since
  }
}];

const p1 = $('Fetch & Filter Couple Photos').first().json.person1Name;
const p2 = $('Fetch & Filter Couple Photos').first().json.person2Name;
const since = $('Fetch & Filter Couple Photos').first().json.sinceDate;
const total = $('Fetch & Filter Couple Photos').first().json.totalFetched;
const botToken = $('Fetch & Filter Couple Photos').first().json.TelegramBotToken;
const chatId = $('Fetch & Filter Couple Photos').first().json.TelegramChatID;

const message = `📷 *Immich Couple Album*

😴 No new couple photos found
👫 ${p1} & ${p2}
🔍 ${total} photos scanned, none matched
📅 Since: ${new Date(since).toLocaleDateString('en-CA')}`;

await helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${botToken}/sendMessage`,
  headers: { 'Content-Type': 'application/json' },
  body: {
    chat_id: chatId,
    text: message,
    parse_mode: 'Markdown'
  },
  json: true
});

return [{ json: { status: 'skipped', message: `No new couple photos of ${p1} & ${p2} since ${since}.` } }];
